import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Img,
  staticFile,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";

export const fps = 25;

const COLORS = {
  bg: "#0A0A0A",
  cyan: "#00B3E3",
  red: "#EF4444",
  darkGrey: "#2A2A2A",
  midGrey: "#1A1A1A",
  dimGrey: "#0F0F0F",
  white: "#FFFFFF",
};

const TRANSITION = 15;

// Scene durations
const S1_DUR = 80 + TRANSITION;
const S2_DUR = 174 + TRANSITION;
const S3_DUR = 173 + TRANSITION;
const S4_DUR = 163 + TRANSITION;
const S5_DUR = 126 + TRANSITION;
const S6_DUR = 210 + TRANSITION;
const OPEN_DUR = 20;
const CLOSE_DUR = 25;

export const durationInFrames =
  OPEN_DUR + S1_DUR + S2_DUR + S3_DUR + S4_DUR + S5_DUR + S6_DUR + CLOSE_DUR -
  TRANSITION * 6 - 20 - 15;

const BlackScreen: React.FC = () => (
  <AbsoluteFill style={{ backgroundColor: COLORS.bg }} />
);

// ─── SCENE 1 ───────────────────────────────────────────────────────────────

const BAR_HEIGHT = 4;
const BAR_GAP = 12;
const CANVAS_W = 3840;
const CANVAS_H = 2160;
const BAR_W = 600;
const TOTAL_BARS = 140;

const Scene1: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: f } = useVideoConfig();

  const centerY = CANVAS_H / 2;
  const totalBarSlot = BAR_HEIGHT + BAR_GAP;

  // Generate bars from center outward, alternating up/down
  const bars: { id: number; y: number; fillSpeed: number; spawnFrame: number }[] = [];
  for (let i = 0; i < TOTAL_BARS; i++) {
    const side = i % 2 === 0 ? 1 : -1;
    const idx = Math.floor(i / 2);
    const y = centerY + side * (idx * totalBarSlot + (i % 2 === 0 ? 0 : totalBarSlot));
    // Spawn acceleration: early bars spawn slowly, later bars spawn fast
    let spawnFrame: number;
    if (i < 3) {
      spawnFrame = i * 12;
    } else if (i < 10) {
      spawnFrame = 36 + (i - 3) * 8;
    } else if (i < 30) {
      spawnFrame = 36 + 56 + (i - 10) * 4;
    } else {
      spawnFrame = 36 + 56 + 80 + (i - 30) * 1.2;
    }
    const fillSpeed = 0.6 + Math.sin(i * 1.3) * 0.4; // varies 0.2 to 1.0
    bars.push({ id: i, y, fillSpeed, spawnFrame });
  }

  return (
    <AbsoluteFill style={{ backgroundColor: COLORS.bg, overflow: "hidden" }}>
      {bars.map((bar) => {
        if (frame < bar.spawnFrame) return null;
        const elapsed = frame - bar.spawnFrame;
        // fill over ~18 frames * fillSpeed
        const fillProgress = Math.min(elapsed / (18 * (1 / bar.fillSpeed)), 1);
        const fillWidth = fillProgress * BAR_W;

        return (
          <div
            key={bar.id}
            style={{
              position: "absolute",
              left: CANVAS_W / 2 - BAR_W / 2,
              top: bar.y - BAR_HEIGHT / 2,
              width: BAR_W,
              height: BAR_HEIGHT,
              backgroundColor: COLORS.darkGrey,
              borderRadius: 2,
              overflow: "hidden",
            }}
          >
            <div
              style={{
                width: fillWidth,
                height: "100%",
                backgroundColor: COLORS.white,
                borderRadius: 2,
              }}
            />
          </div>
        );
      })}
    </AbsoluteFill>
  );
};

// ─── SCENE 2 ───────────────────────────────────────────────────────────────

const Scene2: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: f } = useVideoConfig();

  const centerY = CANVAS_H / 2;
  const totalBarSlot = BAR_HEIGHT + BAR_GAP;

  // Freeze + dim transition (0 to 12 frames)
  const dimProgress = interpolate(frame, [0, 12], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // The highlighted bar: slightly above center, offset right
  const highlightIdx = 0; // the center bar
  const highlightBarY = centerY - 40; // slightly above center
  const highlightBarX = CANVAS_W / 2 - BAR_W / 2 + 60; // slightly right

  // Highlight bar fill animation starts at frame 15
  const fillStart = 15;
  const fillEnd = 40;
  const fillProgress = interpolate(frame, [fillStart, fillEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Label fade
  const labelOpacity = interpolate(frame, [45, 55], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Generate all background bars
  const bars: { id: number; y: number }[] = [];
  for (let i = 0; i < TOTAL_BARS; i++) {
    const side = i % 2 === 0 ? 1 : -1;
    const idx = Math.floor(i / 2);
    const y = centerY + side * (idx * totalBarSlot + (i % 2 === 0 ? 0 : totalBarSlot));
    bars.push({ id: i, y });
  }

  return (
    <AbsoluteFill style={{ backgroundColor: COLORS.bg, overflow: "hidden" }}>
      {/* Background frozen bars */}
      {bars.map((bar) => {
        const isHighlight = bar.y === highlightBarY || (Math.abs(bar.y - highlightBarY) < totalBarSlot * 0.5 && bar.id === 0);
        if (isHighlight) return null; // rendered separately
        const bgColor = interpolate(dimProgress, [0, 1], [0, 15]);
        return (
          <div
            key={bar.id}
            style={{
              position: "absolute",
              left: CANVAS_W / 2 - BAR_W / 2,
              top: bar.y - BAR_HEIGHT / 2,
              width: BAR_W,
              height: BAR_HEIGHT,
              backgroundColor: `rgb(15,15,15)`,
              borderRadius: 2,
              overflow: "hidden",
            }}
          >
            <div
              style={{
                width: `${interpolate(dimProgress, [0, 1], [100, 55])}%`,
                height: "100%",
                backgroundColor: `rgb(${Math.round(interpolate(dimProgress, [0, 1], [255, 26]))},${Math.round(interpolate(dimProgress, [0, 1], [255, 26]))},${Math.round(interpolate(dimProgress, [0, 1], [255, 26]))})`,
                borderRadius: 2,
              }}
            />
          </div>
        );
      })}

      {/* Highlighted cyan bar */}
      <div
        style={{
          position: "absolute",
          left: highlightBarX,
          top: highlightBarY - BAR_HEIGHT / 2,
          width: BAR_W,
          height: BAR_HEIGHT,
          backgroundColor: "#0F0F0F",
          borderRadius: 2,
          overflow: "hidden",
        }}
      >
        <div
          style={{
            width: `${fillProgress * 100}%`,
            height: "100%",
            backgroundColor: COLORS.cyan,
            borderRadius: 2,
          }}
        />
      </div>

      {/* Label */}
      <div
        style={{
          position: "absolute",
          left: highlightBarX + BAR_W + 8,
          top: highlightBarY - 12,
          opacity: labelOpacity,
          fontFamily: "'Inter', sans-serif",
          fontWeight: 600,
          fontSize: 18,
          color: COLORS.white,
          whiteSpace: "nowrap",
        }}
      >
        50K views
      </div>
    </AbsoluteFill>
  );
};

// ─── SCENE 3 ───────────────────────────────────────────────────────────────

const Scene3: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: f } = useVideoConfig();

  const centerY = CANVAS_H / 2;
  const totalBarSlot = BAR_HEIGHT + BAR_GAP;
  const highlightBarY = centerY - 40;
  const highlightBarX = CANVAS_W / 2 - BAR_W / 2 + 60;

  // Glow expand: 0-37 frames
  const glowExpand = interpolate(frame, [0, 37], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  // Label fade out: 0-15 frames
  const labelFade = interpolate(frame, [0, 15], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  // Glow contract: 37-112 frames
  const glowContract = interpolate(frame, [37, 112], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  // Bar color shift back to grey: 60-112
  const barColorShift = interpolate(frame, [60, 112], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const glowOpacity =
    frame < 37
      ? glowExpand * 0.4
      : glowContract * 0.4;
  const glowRadius =
    frame < 37
      ? interpolate(glowExpand, [0, 1], [20, 120])
      : interpolate(glowContract, [0, 1], [120, 20]);

  // Bar fill color: cyan to grey
  const r = Math.round(interpolate(barColorShift, [0, 1], [0, 42]));
  const g = Math.round(interpolate(barColorShift, [0, 1], [179, 42]));
  const b = Math.round(interpolate(barColorShift, [0, 1], [227, 42]));
  const barColor = `rgb(${r},${g},${b})`;

  const bars: { id: number; y: number }[] = [];
  for (let i = 0; i < TOTAL_BARS; i++) {
    const side = i % 2 === 0 ? 1 : -1;
    const idx = Math.floor(i / 2);
    const y = centerY + side * (idx * totalBarSlot + (i % 2 === 0 ? 0 : totalBarSlot));
    bars.push({ id: i, y });
  }

  return (
    <AbsoluteFill style={{ backgroundColor: COLORS.bg, overflow: "hidden" }}>
      {/* Background frozen dim bars */}
      {bars.map((bar) => {
        if (Math.abs(bar.y - highlightBarY) < totalBarSlot * 0.5 && bar.id === 0) return null;
        return (
          <div
            key={bar.id}
            style={{
              position: "absolute",
              left: CANVAS_W / 2 - BAR_W / 2,
              top: bar.y - BAR_HEIGHT / 2,
              width: BAR_W,
              height: BAR_HEIGHT,
              backgroundColor: "#0F0F0F",
              borderRadius: 2,
              overflow: "hidden",
            }}
          >
            <div
              style={{
                width: "55%",
                height: "100%",
                backgroundColor: "#1A1A1A",
                borderRadius: 2,
              }}
            />
          </div>
        );
      })}

      {/* Glow effect */}
      <div
        style={{
          position: "absolute",
          left: highlightBarX + BAR_W / 2 - 200,
          top: highlightBarY - 100,
          width: 400,
          height: 200,
          borderRadius: "50%",
          background: `radial-gradient(ellipse at center, rgba(0,179,227,${glowOpacity}) 0%, transparent 70%)`,
          filter: `blur(${glowRadius}px)`,
          pointerEvents: "none",
        }}
      />

      {/* Highlighted bar */}
      <div
        style={{
          position: "absolute",
          left: highlightBarX,
          top: highlightBarY - BAR_HEIGHT / 2,
          width: BAR_W,
          height: BAR_HEIGHT,
          backgroundColor: "#0F0F0F",
          borderRadius: 2,
          overflow: "hidden",
        }}
      >
        <div
          style={{
            width: "100%",
            height: "100%",
            backgroundColor: barColor,
            borderRadius: 2,
          }}
        />
      </div>

      {/* Fading label */}
      <div
        style={{
          position: "absolute",
          left: highlightBarX + BAR_W + 8,
          top: highlightBarY - 12,
          opacity: labelFade,
          fontFamily: "'Inter', sans-serif",
          fontWeight: 600,
          fontSize: 18,
          color: COLORS.white,
          whiteSpace: "nowrap",
        }}
      >
        50K views
      </div>
    </AbsoluteFill>
  );
};

// ─── SCENE 4 ───────────────────────────────────────────────────────────────

const Scene4: React.FC = () => {
  const frame = useCurrentFrame();

  const centerY = CANVAS_H / 2;
  const totalBarSlot = BAR_HEIGHT + BAR_GAP;

  // Red origin bar: lower-left quadrant
  const originX = CANVAS_W * 0.25;
  const originY = centerY + CANVAS_H * 0.2;

  // All bars positions
  const bars: { id: number; x: number; y: number; col: number; row: number }[] = [];
  const cols = Math.ceil(CANVAS_W / (BAR_W + 20));
  const rows = TOTAL_BARS;
  for (let i = 0; i < TOTAL_BARS; i++) {
    const side = i % 2 === 0 ? 1 : -1;
    const idx = Math.floor(i / 2);
    const y = centerY + side * (idx * totalBarSlot + (i % 2 === 0 ? 0 : totalBarSlot));
    const x = CANVAS_W / 2 - BAR_W / 2;
    bars.push({ id: i, x, y, col: 0, row: i });
  }

  // Compute which bars are red based on distance from origin bar
  // Origin bar is the one closest to originY
  const originBarIdx = bars.reduce((best, b) =>
    Math.abs(b.y - originY) < Math.abs(bars[best].y - originY) ? b.id : best, 0);

  return (
    <AbsoluteFill style={{ backgroundColor: COLORS.bg, overflow: "hidden" }}>
      {bars.map((bar) => {
        const distFromOrigin = Math.abs(bar.id - originBarIdx);
        // Spread timing: origin turns red at frame 5
        // Each step away: 0.3s = ~7.5 frames, accelerating
        let redFrame: number;
        if (distFromOrigin === 0) {
          redFrame = 5;
        } else {
          // Accelerating spread
          const baseDelay = 7;
          const acceleration = Math.max(1, distFromOrigin * 0.85);
          redFrame = 5 + distFromOrigin * Math.max(2, baseDelay - distFromOrigin * 0.3);
        }

        const transitionProgress = interpolate(
          frame,
          [redFrame, redFrame + 5],
          [0, 1],
          { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
        );

        // Only spread to ~60% of bars by end of scene
        const maxSpread = Math.floor(TOTAL_BARS * 0.6 / 2);
        const isRed = distFromOrigin <= maxSpread;

        const r = isRed
          ? Math.round(interpolate(transitionProgress, [0, 1], [26, 239]))
          : 26;
        const g = isRed
          ? Math.round(interpolate(transitionProgress, [0, 1], [26, 68]))
          : 26;
        const b2 = isRed
          ? Math.round(interpolate(transitionProgress, [0, 1], [26, 68]))
          : 26;

        const fillColor = `rgb(${r},${g},${b2})`;
        const fillW = isRed
          ? interpolate(transitionProgress, [0, 1], [55, 78])
          : 55;

        return (
          <div
            key={bar.id}
            style={{
              position: "absolute",
              left: bar.x,
              top: bar.y - BAR_HEIGHT / 2,
              width: BAR_W,
              height: BAR_HEIGHT,
              backgroundColor: "#0F0F0F",
              borderRadius: 2,
              overflow: "hidden",
            }}
          >
            <div
              style={{
                width: `${fillW}%`,
                height: "100%",
                backgroundColor: fillColor,
                borderRadius: 2,
                transition: "none",
              }}
            />
          </div>
        );
      })}
    </AbsoluteFill>
  );
};

// ─── SCENE 5 ───────────────────────────────────────────────────────────────

const Scene5: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: f } = useVideoConfig();

  // Black hold: 0-7 frames
  // Line draws: 7-37 frames (1.2s)
  const lineProgress = interpolate(frame, [8, 38], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Text fades in: 40-55 frames
  const textOpacity = interpolate(frame, [40, 55], [0, 1], {
