          left: 0,
          right: 0,
          textAlign: "center",
          opacity: textOpacity,
          transform: `translateY(${interpolate(textOpacity, [0, 1], [-20, 0])}px)`,
          fontFamily: "'Inter', sans-serif",
          fontWeight: 600,
          fontSize: 32,
          color: COLORS.cyan,
          letterSpacing: "0.05em",
        }}
      >
        by Apify
      </div>
    </AbsoluteFill>
