};

// ─── SCENE 6 ───────────────────────────────────────────────────────────────

const STREAM_BAR_W = 200;
const STREAM_BAR_H = 4;
const CAUGHT_LABELS = ["mention", "creator", "data point"];

const Scene6: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: f } = useVideoConfig();

  // Title slides up and scales down
  const titleProgress = interpolate(frame, [0, 20], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const titleY = interpolate(titleProgress, [0, 1], [CANVAS_H / 2 - 100, 40]);
  const titleScale = interpolate(titleProgress, [0, 1], [1, 0.6]);

  // Streaming bars
  const BAR_SPEED = 18; // px per frame
  const barSpawnInterval = 8; // frames between spawns
  const maxBars = 60;

  const streamBars: {
    id: number;
    spawnFrame: number;
    yOffset: number;
    isCaught: boolean;
    caughtLabelIdx: number;
  }[] = [];

  let caughtCount = 0;
  for (let i = 0; i < maxBars; i++) {
    const spawnFrame = i * barSpawnInterval;
    const yOffset = Math.sin(i * 2.7) * 200; // scatter around center
    // 30% chance of being caught — use deterministic pattern
    const isCaught = (i % 10) < 3 && caughtCount < CAUGHT_LABELS.length;
    const caughtLabelIdx = isCaught ? caughtCount : -1;
    if (isCaught) caughtCount++;
    streamBars.push({ id: i, spawnFrame, yOffset, isCaught, caughtLabelIdx });
  }

  const centerLineY = CANVAS_H / 2;
  const centerLineX = CANVAS_W / 2;
  const catchLineX = centerLineX; // the blue line is the catch point
  const stackX = CANVAS_W * 0.8;
  const stackStartY = centerLineY - 60;
  const stackGap = 16 + STREAM_BAR_H;

  return (
    <AbsoluteFill style={{ backgroundColor: COLORS.bg, overflow: "hidden" }}>
      {/* Title (slides up) */}
      <div
        style={{
          position: "absolute",
          top: titleY,
          left: 0,
          right: 0,
          textAlign: "center",
          fontFamily: "'Inter', sans-serif",
          fontWeight: 600,
          fontSize: 72,
          color: COLORS.white,
          transform: `scale(${titleScale})`,
          transformOrigin: "top center",
        }}
      >
        YouTube Scraper
      </div>
      <div
        style={{
          position: "absolute",
          top: titleY + 72 * titleScale + 8,
          left: 0,
          right: 0,
          textAlign: "center",
          fontFamily: "'Inter', sans-serif",
          fontWeight: 600,
          fontSize: 32 * titleScale,
          color: COLORS.cyan,
          transform: `scale(${titleScale})`,
          transformOrigin: "top center",
        }}
      >
        by Apify
      </div>

      {/* Blue center scan line */}
      <div
        style={{
          position: "absolute",
          top: centerLineY - 1,
          left: 0,
          right: 0,
          height: 2,
          backgroundColor: COLORS.cyan,
          opacity: 0.85,
        }}
      />

      {/* Streaming bars */}
      {streamBars.map((bar) => {
        if (frame < bar.spawnFrame) return null;
        const elapsed = frame - bar.spawnFrame;
        const rawX = -STREAM_BAR_W + elapsed * BAR_SPEED;
        const barY = centerLineY + bar.yOffset;

        if (bar.isCaught) {
          // The bar travels until it hits the center line, then snaps to stack
          const catchTime = (catchLineX + STREAM_BAR_W) / BAR_SPEED;
          const hasCaught = elapsed >= catchTime;
          const stackY = stackStartY + bar.caughtLabelIdx * stackGap;

          if (!hasCaught) {
            const flashFrame = Math.round(catchTime);
            const isFlashing = Math.abs(elapsed - flashFrame) < 1;
            return (
              <div
                key={bar.id}
                style={{
                  position: "absolute",
                  top: barY - STREAM_BAR_H / 2,
                  left: rawX,
                  width: STREAM_BAR_W,
                  height: STREAM_BAR_H,
                  backgroundColor: isFlashing ? COLORS.white : COLORS.darkGrey,
                  borderRadius: 2,
                }}
              />
            );
          } else {
            // Snapped to stack
            const snapProgress = interpolate(elapsed - catchTime, [0, 12], [0, 1], {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            });
            const labelOpacity = interpolate(elapsed - catchTime, [12, 20], [0, 1], {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            });
            return (
              <React.Fragment key={bar.id}>
                <div
                  style={{
                    position: "absolute",
                    top: stackY - STREAM_BAR_H / 2,
                    left: interpolate(snapProgress, [0, 1], [catchLineX, stackX - STREAM_BAR_W / 2]),
                    width: STREAM_BAR_W,
                    height: STREAM_BAR_H,
                    backgroundColor: COLORS.cyan,
                    borderRadius: 2,
                    opacity: snapProgress,
                  }}
                />
                {bar.caughtLabelIdx < CAUGHT_LABELS.length && (
                  <div
                    style={{
                      position: "absolute",
                      top: stackY - 12,
                      left: stackX + STREAM_BAR_W / 2 + 12,
                      opacity: labelOpacity,
                      fontFamily: "'Inter', sans-serif",
                      fontWeight: 600,
                      fontSize: 16,
                      color: COLORS.white,
                      whiteSpace: "nowrap",
                    }}
                  >
                    {CAUGHT_LABELS[bar.caughtLabelIdx]}
                  </div>
                )}
              </React.Fragment>
            );
          }
        } else {
          // Regular bar passes through and fades off right edge
          const fadeStart = CANVAS_W - STREAM_BAR_W;
          const opacity =
            rawX > fadeStart
              ? interpolate(rawX, [fadeStart, CANVAS_W + STREAM_BAR_W], [1, 0], {
                  extrapolateLeft: "clamp",
                  extrapolateRight: "clamp",
                })
              : 1;
          if (rawX > CANVAS_W + STREAM_BAR_W) return null;
          return (
            <div
              key={bar.id}
              style={{
                position: "absolute",
                top: barY - STREAM_BAR_H / 2,
                left: rawX,
                width: STREAM_BAR_W,
                height: STREAM_BAR_H,
                backgroundColor: COLORS.darkGrey,
                borderRadius: 2,
                opacity,
              }}
            />
          );
        }
      })}
    </AbsoluteFill>
  );
};

// ─── MAIN COMPOSITION ──────────────────────────────────────────────────────

const MainComposition: React.FC = () => {
  return (
    <TransitionSeries>
      <TransitionSeries.Sequence durationInFrames={OPEN_DUR}>
        <BlackScreen />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: 15 })}
      />

      <TransitionSeries.Sequence durationInFrames={S1_DUR}>
        <Scene1 />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      <TransitionSeries.Sequence durationInFrames={S2_DUR}>
        <Scene2 />
